static const uint32_t frames_run_count = sizeof(frames_table) / sizeof(frames_table[0]);

const uint32_t frames64_count = 6572;

static uint8_t frames_decode_buffer[512];

static const Graphics_Image frames_image = {
    IMAGE_FMT_1BPP_UNCOMP,
    64,
    64,
    2,
    palette_all_1BPP_UNCOMP,
    frames_decode_buffer
};

static void frames_rle_decode(const uint8_t *rle, uint16_t rle_len, uint8_t *out) {
    uint8_t color = 0;
    uint32_t pix = 0;
    uint16_t i;
    for (i = 0; i < rle_len; i++) {
        uint16_t run = rle[i];
        uint16_t j;
        for (j = 0; j < run; j++) {
            uint32_t byte_idx = pix >> 3;
            uint8_t bit_idx = (uint8_t)(7 - (pix & 7));
            if (color)
                out[byte_idx] |= (uint8_t)(1 << bit_idx);
            else
                out[byte_idx] &= (uint8_t)~(1 << bit_idx);
            pix++;
        }
        color = (uint8_t)(1 - color);
    }
}

const Graphics_Image *frames64_get_frame(uint32_t index) {
    uint32_t remaining = index;
    uint32_t i;
    for (i = 0; i < frames_run_count; i++) {
        if (remaining < frames_table[i].repeat) {
            frames_rle_decode(frames_table[i].data, frames_table[i].len, frames_decode_buffer);
            return &frames_image;
        }
        remaining -= frames_table[i].repeat;
    }
    return &frames_image;
}
